/**
 * Design and operating ranges of every pyro-line register position — OSW-PE-SNL-PYR-01 Rev. 02
 * "Pyro-Line Sensor List with Ranges" (machine-wise register, for site verification). Generated from the
 * document (rev02/spec.json); the text fields are as printed.
 *
 * design   instrument (transmitter) range, LRV – URV
 * nominal  normal operating value or band at design throughput
 * L / H    first level (Alert): low / high set-point
 * LL / HH  second level (Critical): low-low / high-high set-point
 * For draft (negative pressure) H means less negative than nominal. "–" = not used.
 * `LH` / `LLHH` keep the printed "L / H" and "LL / HH" cells; relative rows ("nominal ± 20 %", "SP ± 5 %",
 * "±5 % vs command", "H = band + 30 °C", "±10 % of mean") stay text only — the alarm matrix (`./limits`)
 * judges them against the reference model, the set-point or the command.
 *
 * Rev. 02 is in our units (% FLA, % rated, mbar, °C …), so every numeric row maps one to one onto its signal
 * (`conv` "same"); status rows carry the text only (`conv` "none").
 *
 * Pure data, no React and no server imports.
 */

export interface PyroRangeRow {
  tag: string;
  /** Signal whose numbers this row sets, when not `tag` itself. */
  appliesTo?: string;
  docUnit: string;
  design: string;
  nominal: string;
  /** "L / H" and "LL / HH" as printed. */
  LH: string;
  LLHH: string;
  LL: string;
  L: string;
  H: string;
  HH: string;
  /** Register class (online, calculated, conditional, manual, tag on hold). */
  regClass: string;
  remarks: string;
  /**
   * How the numbers map onto our signal's unit: same unit, or none (status / relative rows: the text only).
   * Older revisions also used mmWG → mbar, bar(g) → mbar and % of a rating; Rev. 02 needs neither.
   */
  conv: "same" | "mmwg" | "barg" | "pct" | "none";
  designLo: number | null;
  designHi: number | null;
  nominalLo: number | null;
  nominalHi: number | null;
  ll: number | null;
  l: number | null;
  h: number | null;
  hh: number | null;
}

