export const PYRO_RANGE_BY_SIGNAL: Record<string, PyroRangeRow> = Object.fromEntries(Object.values(PYRO_RANGES).map((r) => [r.appliesTo ?? r.tag, r]));

/** A row's numbers in our signal's unit; `base` (the signal's normal value) scales % ratings. */
export function rangeInUnit(r: PyroRangeRow, base: number): {
  factor: number;
  basis: string | null;
  designLo: number | null;
  designHi: number | null;
  nominalLo: number | null;
  nominalHi: number | null;
  ll: number | null;
  l: number | null;
  h: number | null;
  hh: number | null;
} | null {
  if (r.conv === "none") return null;
  let factor = 1;
  let basis: string | null = null;
  if (r.conv === "mmwg") factor = 1 / 10.197;
  else if (r.conv === "barg") factor = 1000;
  else if (r.conv === "pct") {
    const mid = r.nominalLo !== null && r.nominalHi !== null ? (r.nominalLo + r.nominalHi) / 2 : null;
    if (!mid || !Number.isFinite(base) || base === 0) return null;
    factor = base / mid;
    basis = `100 % taken as ${+(factor * 100).toPrecision(4)} (our normal value at the middle of the nominal band) until the nameplate or design figure is confirmed`;
  }
  const k = (v: number | null) => (v === null ? null : +(v * factor).toPrecision(6));
  const lo = k(r.nominalLo);
  const hi = k(r.nominalHi);
  return {
    factor,
    basis,
    designLo: k(r.designLo),
    designHi: k(r.designHi),
    nominalLo: lo !== null && hi !== null ? Math.min(lo, hi) : lo,
    nominalHi: lo !== null && hi !== null ? Math.max(lo, hi) : hi,
    ll: k(r.ll),
    l: k(r.l),
    h: k(r.h),
    hh: k(r.hh),
  };
}
